-- Generated by model/lib/sql/generate.mjs. Loads Marketing Split IN from cells/Marketing Split IN.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/Marketing Split IN.csv
INSERT INTO "Marketing Split IN" SELECT coalesce(k0."Brand", fpabench_error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k1."Country", fpabench_error('cells name a member Country does not have: ' || c."Country")), coalesce(k2."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k3."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Brand" k0 ON k0.name = c."Brand" LEFT JOIN "dim Country" k1 ON k1.name = c."Country" LEFT JOIN "dim Versions" k2 ON k2.name = c."Versions" LEFT JOIN "dim Years" k3 ON k3.name = c."Years"
GROUP BY 1, 2, 3, 4
ON CONFLICT ("Brand", "Country", "Versions", "Years") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "Marketing Split IN";
